-- ============================================================
-- RESET & IMPORT PATIENTS COMPLET — HAITI REH-CARE
-- Total: 1098 patients depuis le document Patient.PDF
-- Rattachés au Siège Principal dans erp_annexes (code PAP/PRN)
-- ============================================================

BEGIN;

-- 1. Eviter tout blocage d'unicite sur #Dossier et garantir l'acces lecture
DROP INDEX IF EXISTS idx_patients_code;
CREATE INDEX IF NOT EXISTS idx_patients_code ON erp_patients(code);

DROP POLICY IF EXISTS "patients_all_read" ON erp_patients;
CREATE POLICY "patients_all_read" ON erp_patients FOR SELECT USING (is_active = true);

-- 2. Detacher et vider les tables dépendantes pour supprimer sans erreur FK
UPDATE erp_patient_demandes SET patient_id = NULL WHERE patient_id IS NOT NULL;
UPDATE erp_ventes SET patient_id = NULL WHERE patient_id IS NOT NULL;
UPDATE erp_facturation_medical SET patient_id = NULL WHERE patient_id IS NOT NULL;
UPDATE erp_ordonnances SET patient_id = NULL WHERE patient_id IS NOT NULL;
UPDATE erp_encaissements SET patient_id = NULL WHERE patient_id IS NOT NULL;
UPDATE erp_atelier_orders SET patient_id = NULL WHERE patient_id IS NOT NULL;
UPDATE erp_reclamations SET patient_id = NULL WHERE patient_id IS NOT NULL;
DELETE FROM erp_patient_reevaluations;
DELETE FROM erp_evaluations;
DELETE FROM erp_seances;
DELETE FROM erp_rdv;
DELETE FROM erp_protheses;
DELETE FROM erp_ortheses;
DELETE FROM erp_patients;

-- 3. Inserer tous les 1098 patients

-- 4. Rattacher tous les patients au Siège Principal (is_principale = true / code PAP / PRN)
DO $$
DECLARE
  v_annexe_id uuid;
  v_enterprise_id uuid;
BEGIN
  -- Trouver l'ID de l'entreprise
  SELECT id INTO v_enterprise_id FROM erp_enterprise_registrations
   WHERE statut = 'active'
   ORDER BY (lower(company_email) = 'haitirecareerp@gmail.com') DESC, created_at
   LIMIT 1;

  -- Trouver l'annexe du Siège Principal (PAP ou PRN ou is_principale)
  SELECT id INTO v_annexe_id FROM erp_annexes
   WHERE is_active = true
   ORDER BY is_principale DESC, (code = 'PAP') DESC, (code = 'PRN') DESC, created_at
   LIMIT 1;

  -- Si aucune annexe n'existe encore, créer le Siège Principal (PAP)
  IF v_annexe_id IS NULL THEN
    VALUES (v_enterprise_id, 'PAP', 'Siège Principal (Port-au-Prince)', 'Port-au-Prince', true, true)
    RETURNING id INTO v_annexe_id;
  END IF;

  -- Assigner l'annexe du Siège Principal et l'entreprise à tous les nouveaux patients
  IF v_annexe_id IS NOT NULL THEN
    UPDATE erp_patients
       SET annexe_id = v_annexe_id,
           enterprise_id = COALESCE(enterprise_id, v_enterprise_id);
  END IF;
END $$;

COMMIT;

-- Vérification : nombre de patients et code de l'annexe rattachée
SELECT
  COUNT(p.id) AS total_patients_inseres,
  a.code AS code_annexe_siege,
  a.nom AS nom_annexe_siege
FROM erp_patients p
LEFT JOIN erp_annexes a ON a.id = p.annexe_id
GROUP BY a.code, a.nom;